using Callsign.Extensions;

namespace Callsign.UI.Services;

public sealed record CommandDiscoveryEntry(
    string Category,
    string Phrase,
    string Description,
    CallsignCommandRiskTier RiskTier,
    CallsignCommandApprovalRequirement ApprovalRequirement,
    string Source,
    IReadOnlyList<string>? VoicePhrases = null,
    IReadOnlyList<string>? Examples = null,
    CallsignPackTier Tier = CallsignPackTier.Free,
    CallsignPackLoadStatus LoadStatus = CallsignPackLoadStatus.Loaded,
    string Availability = "Available");

public static class CommandDiscoveryService
{
    private const string BuiltInSource = "Open Core";

    public static IReadOnlyList<CommandDiscoveryEntry> GetCommands(CallsignCommandRegistry? registry = null)
    {
        var commands = new List<CommandDiscoveryEntry>();
        commands.AddRange(GetBuiltInCommands().Select(command => command with { Source = BuiltInSource }));

        registry ??= CallsignCommandRegistry.Shared;
        foreach (var command in registry.GetCommands())
        {
            var definition = command.Definition;
            var phrase = definition.VoicePhrases.FirstOrDefault() ?? command.CommandDisplayName;
            var examples = MergeExamples(definition.VoicePhrases, definition.Examples);
            var availability = FormatAvailability(command.LoadStatus, command.Tier);
            var sourcePrefix = command.IsCommunity ? "Community pack" : "Trusted pack";
            commands.Add(new CommandDiscoveryEntry(
                string.IsNullOrWhiteSpace(definition.Category) ? definition.Kind.ToString() : definition.Category,
                phrase,
                definition.HelpText ?? definition.Description,
                definition.RiskTier,
                definition.ApprovalRequirement,
                $"{sourcePrefix}: {command.PackDisplayName} [{command.Tier}; {availability}]",
                definition.VoicePhrases,
                examples,
                command.Tier,
                command.LoadStatus,
                availability));
        }

        return commands
            .OrderBy(command => command.Category, StringComparer.OrdinalIgnoreCase)
            .ThenBy(command => command.Phrase, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    public static string BuildHelpText(string? filter = null, CallsignCommandRegistry? registry = null)
    {
        var commands = GetCommands(registry);
        if (!string.IsNullOrWhiteSpace(filter))
            commands = commands.Where(command => MatchesHelpFilter(command, filter)).ToArray();

        var groups = commands
            .GroupBy(command => command.Category)
            .OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase);

        var lines = new List<string>
        {
            "Callsign command palette",
            string.Empty,
            "Say Callsign, verify your callsign, then speak one of these commands.",
            "Try getting started, open release proof, read release proof, read evidence status, read evidence header, read release blockers, read next proof, read proof steps, create proof note, create all proof notes, create evidence draft, open evidence draft, read evidence draft, read proof notes, open proof notes, read release gates, read visual status, open installer, read updates status, read voice mode status, read check-in status, read restart proof, read import summary again, read watch status, read paywall status, or open release evidence, open manual evidence, or open manual evidence checklist, open checklist, to reopen the setup walkthrough.",
            "Common visible system commands: task view, quick settings, notification center, open task manager, show snap layouts, minimize window, maximize window, restore window, close window.",
            "Search tips: try free parity, voice access parity, category:System, category:Files tab, category:File search, category:Packs, file search, windowing, media, category:Browser, category:Dictation, tier:free, tier:pro, tier:advanced, paid, status:available, status:disabled, status:gated, import extension pack, import extension folder, import dll, drop dll, drop dll folder, drag and drop dll, drag and drop dll folder, update extension pack, rollback extension pack, refresh packs, open packs folder, read watch status, watched folder, or source:open core, source:free, source:community, source:trusted, or source:Sample Pack.",
            string.Empty
        };

        if (!string.IsNullOrWhiteSpace(filter))
        {
            lines.Add($"Filtered view: {filter.Trim()}");
            lines.Add(string.Empty);
        }

        foreach (var group in groups)
        {
            lines.Add(group.Key);
            foreach (var command in group)
            {
                var aliases = command.VoicePhrases is { Count: > 1 }
                    ? $" ({string.Join(", ", command.VoicePhrases.Skip(1).Take(4))})"
                    : string.Empty;
                var examples = FormatExampleHint(command);
                lines.Add($"- {command.Phrase}{aliases}: {command.Description}{examples} [Source: {command.Source} | Tier: {command.Tier} | Availability: {command.Availability} | Approval: {FormatApproval(command.ApprovalRequirement)}]");
            }
            lines.Add(string.Empty);
        }

        lines.Add("Safety");
        lines.Add("- cancel: stop the current session");
        lines.Add("- stop listening: stop voice capture");
        lines.Add("- reset session: return to idle");

        return string.Join(Environment.NewLine, lines);
    }

    public static string BuildHelpText(CallsignCommandRegistry? registry = null) =>
        BuildHelpText(filter: null, registry);

    internal static bool MatchesHelpFilter(CommandDiscoveryEntry command, string filter)
    {
        if (string.IsNullOrWhiteSpace(filter))
            return true;

        var trimmed = filter.Trim();
        if (TryGetFilterValue(trimmed, "tier", out var tierValue))
            return string.Equals(command.Tier.ToString(), tierValue, StringComparison.OrdinalIgnoreCase)
                || string.Equals(command.Tier.ToString(), tierValue, StringComparison.OrdinalIgnoreCase);

        if (string.Equals(trimmed, "paid", StringComparison.OrdinalIgnoreCase)
            || string.Equals(trimmed, "premium", StringComparison.OrdinalIgnoreCase))
            return command.Tier is CallsignPackTier.Pro or CallsignPackTier.Advanced;

        if (IsFreeParityFilter(trimmed))
            return command.Tier == CallsignPackTier.Free && IsBuiltInSource(command.Source);

        if (TryGetFilterValue(trimmed, "status", out var statusValue))
            return MatchesStatus(command, statusValue);

        if (TryGetFilterValue(trimmed, "source", out var sourceValue))
            return IsBuiltInSourceFilter(sourceValue)
                ? IsBuiltInSource(command.Source)
                : Contains(command.Source, sourceValue);

        if (TryGetFilterValue(trimmed, "category", out var categoryValue))
            return Contains(command.Category, categoryValue);

        if (TryGetFilterValue(trimmed, "approval", out var approvalValue))
            return MatchesApproval(command, approvalValue);

        if (TryGetFilterValue(trimmed, "risk", out var riskValue))
            return MatchesRisk(command, riskValue);

        if (IsExtensionFilter(trimmed))
            return !IsBuiltInSource(command.Source);

        if (IsSafetyFilter(trimmed))
            return IsCoreSessionSafetyCommand(command);

        if (IsWindowingFilter(trimmed))
            return IsWindowingCommand(command);

        if (string.Equals(trimmed, "plans", StringComparison.OrdinalIgnoreCase)
            || string.Equals(trimmed, "paywall", StringComparison.OrdinalIgnoreCase)
            || string.Equals(trimmed, "pay wall", StringComparison.OrdinalIgnoreCase)
            || string.Equals(trimmed, "paid wall", StringComparison.OrdinalIgnoreCase)
            || string.Equals(trimmed, "upgrade", StringComparison.OrdinalIgnoreCase)
            || string.Equals(trimmed, "subscription", StringComparison.OrdinalIgnoreCase))
            return (string.Equals(command.Category, "Navigation", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(command.Phrase, "open plans", StringComparison.OrdinalIgnoreCase))
                || (string.Equals(command.Category, "Plans", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(command.Phrase, "read plans status", StringComparison.OrdinalIgnoreCase))
                || (string.Equals(command.Category, "Plans", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(command.Phrase, "read paywall status", StringComparison.OrdinalIgnoreCase));

        return Contains(command.Category, trimmed)
            || Contains(command.Phrase, trimmed)
            || Contains(command.Description, trimmed)
            || Contains(command.Source, trimmed)
            || Contains(command.Availability, trimmed)
            || Contains(command.Tier.ToString(), trimmed)
            || Contains(command.LoadStatus.ToString(), trimmed)
            || Contains(FormatRisk(command.RiskTier), trimmed)
            || Contains(command.RiskTier.ToString(), trimmed)
            || Contains(FormatApproval(command.ApprovalRequirement), trimmed)
            || Contains(command.ApprovalRequirement.ToString(), trimmed)
            || (command.VoicePhrases?.Any(phrase => Contains(phrase, trimmed)) == true)
            || (command.Examples?.Any(example => Contains(example, trimmed)) == true);
    }

